package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.configuration.RuntimeConfigurationRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class CapacityRuntimeInputsTest {
 final ObjectMapper mapper=new ObjectMapper();final RuntimeConfigurationRepository repository=mock(RuntimeConfigurationRepository.class);final RuntimeConfigurationCatalog catalog=new RuntimeConfigurationCatalog(mapper);final CapacityRuntimeInputs service=new CapacityRuntimeInputs(repository,catalog,mapper);
 final Membership member=new Membership("55000000-0000-4000-8000-000000000003","55000000-0000-4000-8000-000000000001","padmin",2,true);
 List<Map<String,Object>> rows(){return new ArrayList<>(RuntimeConfigurationRepository.CAPACITY_KEYS.stream().map(k->ApiResponse.map("tenant_id",member.tenantId(),"configuration_key",k,"source","postgresql","status","UNCONFIGURED","effective_value",null,"selected_release",null,"observed_at","2026-10-15T00:00:00Z")).toList());}
 void active(List<Map<String,Object>> rows,int i,Object value){var r=rows.get(i);r.put("status","ACTIVE");r.put("effective_value",value);r.put("selected_release",ApiResponse.map("id","55000000-0000-4000-8000-000000000004","version",3,"definition_hash",catalog.hash(r.get("configuration_key").toString()),"expires_at",null,"published_by","private-not-returned"));}
 List<Map<String,Object>> result(List<Map<String,Object>> rows){when(repository.capacityInputs(any())).thenReturn(rows);return (List<Map<String,Object>>)service.read(member,"trace").get("items");}
 @Test void missingNeverInventsCapacityDefaults(){for(var r:result(rows())){assertEquals("UNCONFIGURED",r.get("status"));assertNull(r.get("input_value"));assertNull(r.get("value"));}}
 @Test void perKeySchemaSeparatesBytesRatiosAndMultipliers(){for(var entry:Map.of("capacity.bytes_per_value",128,"capacity.trend_ratio",0.25,"capacity.headroom",1.2).entrySet())assertDoesNotThrow(()->catalog.validate(entry.getKey(),mapper.valueToTree(entry.getValue())));assertDoesNotThrow(()->catalog.validate("capacity.trend_ratio",mapper.valueToTree(0)));assertThrows(DomainException.class,()->catalog.validate("capacity.bytes_per_value",mapper.valueToTree(0)));assertThrows(DomainException.class,()->catalog.validate("capacity.trend_ratio",mapper.valueToTree(1.2)));assertThrows(DomainException.class,()->catalog.validate("capacity.headroom",mapper.valueToTree(0.2)));}
 @Test void convertsMultiplierToExtraRatioWithoutDoubleArithmetic(){var rows=rows();active(rows,0,60);active(rows,1,90);active(rows,2,365);active(rows,3,128);active(rows,4,0);active(rows,5,new java.math.BigDecimal("1.2"));active(rows,6,3600);var r=result(rows);assertEquals(List.of("60","90","365","128","0","0.2","3600"),r.stream().map(x->x.get("input_value")).toList());assertFalse(r.toString().contains("published_by"));assertFalse(r.toString().contains("private-not-returned"));}
 @Test void expiredDisabledAndChangedDefinitionsNeverUsePriorValues(){for(String state:List.of("EXPIRED","DISABLED")){var rows=rows();active(rows,3,128);rows.get(3).put("status",state);rows.get(3).put("effective_value",null);assertNull(result(rows).get(3).get("input_value"));}var rows=rows();active(rows,3,128);((Map<String,Object>)rows.get(3).get("selected_release")).put("definition_hash","a".repeat(64));assertEquals("DEFINITION_CHANGED",result(rows).get(3).get("status"));}
 @Test void unsupportedModelRangesDoNotClampOrPartiallyApply(){var rows=rows();active(rows,5,3);active(rows,1,2147483648L);var r=result(rows);for(int i:List.of(1,5)){assertEquals("INCOMPATIBLE_MODEL",r.get(i).get("status"));assertNull(r.get(i).get("input_value"));}active(rows,3,-128);assertEquals("INVALID_VALUE",result(rows).get(3).get("status"));}
 @Test void inconsistentScopeClockOrderingOrDatabaseFailureIsAnError(){var rows=rows();rows.get(0).put("tenant_id","other");assertThrows(DomainException.class,()->result(rows));var clocks=rows();clocks.get(1).put("observed_at","2026-10-15T00:00:01Z");assertThrows(DomainException.class,()->result(clocks));doThrow(new DomainException(503,"UPSTREAM_UNAVAILABLE","db")).when(repository).capacityInputs(any());assertThrows(DomainException.class,()->service.read(member,"trace"));}
 @Test void controllerRejectsOtherRolesQueryOverridesAndRevokedMembership(){var platform=mock(PlatformRepository.class);var controller=new CapacityRuntimeInputsController(platform,service);var request=new MockHttpServletRequest();request.setUserPrincipal(()->member.userId());request.getSession().setAttribute("mop.tenant_id",member.tenantId());when(platform.membership(member.userId(),member.tenantId())).thenReturn(Optional.of(member));when(repository.capacityInputs(any())).thenReturn(rows());assertDoesNotThrow(()->controller.read(request));request.addParameter("tenant_id","other");assertEquals(400,assertThrows(DomainException.class,()->controller.read(request)).status);request.removeAllParameters();when(platform.membership(member.userId(),member.tenantId())).thenReturn(Optional.of(new Membership(member.userId(),member.tenantId(),"viewer",2,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.read(request)).status);when(platform.membership(member.userId(),member.tenantId())).thenReturn(Optional.of(member),Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.read(request)).status);}
}
